css:
.stcbl-print {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 12px;
    color: #000;
    line-height: 1.3;
    padding: 8mm 12mm 10mm 12mm;
}

@page {
    size: A4;
    margin: 10mm;
}

/* Header row */
.header-row {
    width: 100%;
    display: table;
    table-layout: fixed;
    margin: 0 0 12px 0;
    padding: 0;
}

.header-left,
.header-right {
    display: table-cell;
    padding: 0;
}

.header-left {
    width: 106%;
    vertical-align: middle;
}

.header-right {
    width: 24%;
    vertical-align: middle;
    text-align: right;
    padding-top: 24px;
    padding-right: 0;
}

/* Clean letterhead spacing */
.hidden-pdf {
    margin: 0;
    padding: 0;
}

.letter-head {
    width: 100%;
    margin: 0;
    padding: 0;
}

.header-with-qr {
    margin: 0;
    padding: 0;
}

/* Make header a little bigger and more centered */
.letter-head img,
.letter-head .company-logo,
.letter-head .header-logo {
    max-height: 85px !important;
    height: auto !important;
    width: auto !important;
    display: inline-block !important;
}

.letter-head {
    text-align: center;
}

.letter-head h1,
.letter-head h2,
.letter-head h3,
.letter-head h4 {
    margin: 0 !important;
    line-height: 1.12 !important;
}

.letter-head p,
.letter-head div,
.letter-head span {
    line-height: 1.15 !important;
}

/* Right side TPN and date */
.tpn-line {
    font-size: 11px;
    line-height: 1.2;
    margin: 0 0 5px 0;
    white-space: nowrap;
}

.date-line {
    font-size: 11px;
    line-height: 1.2;
    margin: 0;
    white-space: nowrap;
}

/* Address */
.address-section {
    margin-top: 2px;
    margin-bottom: 14px;
    line-height: 1.35;
}

/* Subject */
.subject-section {
    margin-bottom: 12px;
}

/* Body */
.body-section {
    margin-bottom: 14px;
}

.body-text {
    margin-top: 6px;
}

/* Section headings */
.section-heading {
    font-size: 13px;
    font-weight: bold;
    margin: 10px 0 4px 0;
}

/* Tables */
.detail-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    margin-bottom: 8px;
}

.detail-table td {
    border: 1px solid #222;
    padding: 4px 6px;
    font-size: 12px;
    line-height: 1.2;
    vertical-align: middle;
}

.col-no {
    width: 8%;
}

.col-label {
    width: 22%;
    font-weight: 500;
}

.col-value {
    width: 70%;
}

/* Footer */
.footer-text {
    margin-top: 18px;
    margin-bottom: 50px;
}

.signature-block {
    margin-top: 10px;
    line-height: 1.5;
}

/* Avoid break issues */
.header-row,
.address-section,
.subject-section,
.body-section,
.footer-text,
.signature-block {
    page-break-inside: avoid;
}

.detail-table tr {
    page-break-inside: avoid;
}
